import{_ as t,o,c,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"FR 3.8.1 — Connect Social Account","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/07-publishing-social/3-8-1-connect-social-account/spec.md","filePath":"feature/srs/07-publishing-social/3-8-1-connect-social-account/spec.md"}'),n={name:"feature/srs/07-publishing-social/3-8-1-connect-social-account/spec.md"};function s(i,e,r,d,l,u){return o(),c("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-8-1-—-connect-social-account" tabindex="-1">FR 3.8.1 — Connect Social Account <a class="header-anchor" href="#fr-3-8-1-—-connect-social-account" aria-label="Permalink to &quot;FR 3.8.1 — Connect Social Account&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.8.1</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-107</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Connect Social Account</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Publishing &amp; Social (<code>3.8</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20, BR-52, BR-53</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01, MSG02, MSG03, MSG07, MSG42</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Authorize and bind a Workspace&#39;s official social publishing accounts across the 4 supported platforms (<strong>Facebook Page</strong>, <strong>Instagram Business/Creator</strong>, <strong>TikTok</strong>, and <strong>Threads</strong>) via OAuth 2.0 + CSRF cookie binding (<code>bh_oauth_state</code>) + PKCE (<code>TikTok</code>), encrypting access/refresh tokens with AES-256-GCM (<code>CryptoUtils</code>) and synchronizing Workspace account metadata into MongoDB <code>social_accounts</code>.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized member holding <code>Owner, Manager, Client</code> in a Workspace, I want to execute <strong>Connect Social Account</strong> reliably across BrandHub&#39;s supported social publishing pipeline (<strong>Facebook, Instagram, TikTok, Threads</strong>) so that approved brand content is delivered, previewed, scheduled, and audited safely with full tenant isolation (<code>BR-20, BR-52, BR-53</code>).</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Canonical Role &amp; Workspace Scope (<code>BR-20</code>):</strong> Only authenticated Workspace members with role in <code>Owner, Manager, Client</code> may invoke the public REST endpoints for <code>Connect Social Account</code>; unauthorized roles or cross-workspace requests fail deterministically with <code>403 FORBIDDEN</code> (<code>MSG07</code>).</li><li><strong>Four-Platform Scope Discipline:</strong> Strictly supports <strong>Facebook</strong>, <strong>Instagram</strong>, <strong>TikTok</strong>, and <strong>Threads</strong> — legacy/de-scoped platforms (such as Zalo OA or LinkedIn) are rejected at validation boundaries (<code>MSG02</code>).</li><li><strong>Production Pipeline &amp; Idempotency:</strong></li></ol><ul><li><strong>1. Pre-Authorization &amp; Ticket Issuance:</strong> <code>SocialOAuthController</code> validates that <code>X-User-Id</code> holds <code>Owner</code>, <code>Manager</code>, or <code>Client</code> permission on <code>workspaceId</code> via <code>BusinessServiceClient</code>. Generates a cryptographic <code>state</code> bound to HttpOnly cookie <code>bh_oauth_state</code> and a <code>60,000 ms</code> single-use ticket (<code>pendingConnectTickets</code>) so Bearer JWTs never leak in browser URL query strings.</li><li><strong>2. Provider-Specific OAuth Handshake:</strong> Meta Graph API <code>v19.0</code> exchanges short-lived user tokens for long-lived Page/IG Business tokens; TikTok OAuth v2 (<code>https://open.tiktokapis.com/v2/oauth/token/</code>) validates PKCE <code>code_verifier</code> and retrieves creator profile (<code>https://open.tiktokapis.com/v2/user/info/</code>); Threads OAuth (<code>https://graph.threads.net/oauth/access_token</code> -&gt; <code>/access_token</code>) upgrades to 60-day long-lived token.</li><li><strong>3. AES-256-GCM Encryption &amp; Idempotent Reactivation:</strong> Tokens are encrypted with <code>CryptoUtils</code> (<code>publisher.token-decryption-key</code>) and synced to <code>brandhub-business-service</code> (<code>SocialAccountDocument</code> in MongoDB <code>social_accounts</code>). Reconnecting a previously disconnected external <code>platformAccountId</code> in the same Workspace reactivates the existing document (<code>status = CONNECTED</code>) so historical post analytics stay linked.</li><li><strong>4. Proactive Token Refresh (<code>TokenRefreshScheduler</code>):</strong> Queries <code>GET /api/v1/internal/social-accounts/expiring?days=7</code> and refreshes expiring TikTok/Threads/Meta tokens automatically, or flags <code>TOKEN_EXPIRED</code> via <code>POST /api/v1/internal/social-accounts/token-refresh-failed</code>.</li></ul><ol start="4"><li><strong>Token &amp; Credential Security:</strong> Raw OAuth access/refresh tokens are encrypted at rest via AES-256-GCM (<code>CryptoUtils</code>) and never returned in client-facing <code>ApiResponse&lt;T&gt;</code> DTOs or written to application logs.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> All buttons, platform badges, status pills, validation alerts, and modal copy use synchronized key-parallel entries (<code>connections.platforms.*</code>, <code>connections.actions.connect</code>, <code>connections.status.*</code>, <code>connections.errors.oauthCancelled</code> in <code>src/i18n/locales/{vi,en}/connections.json</code>) on <code>brandhub-web</code> and <code>tr()</code> on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces (<code>pages/connections/index.tsx</code>, <code>pages/client/components/ClientSocialAccounts.tsx</code>, <code>components/common/SocialPlatformBadge.tsx</code> on Web and <code>src/screens/more/SocialAccountsScreen.tsx</code> (<code>expo-web-browser</code> OAuth flow), <code>src/services/socialAccountService.ts</code> on Mobile) use semantic CSS variables / Tailwind <code>dark:</code> variants and <code>useAppPreferences().palette</code> tokens with WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/connections/index.tsx</code>, <code>pages/client/components/ClientSocialAccounts.tsx</code>, <code>components/common/SocialPlatformBadge.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/SocialAccountsScreen.tsx</code> (<code>expo-web-browser</code> OAuth flow), <code>src/services/socialAccountService.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / In-Flight:</strong> Skeleton placeholders on read views; spinner + disabled action button on mutations to prevent duplicate submissions.</li><li><strong>Empty:</strong> Contextual guidance card (e.g., prompt to connect social account via FR 3.8.1 or create/schedule a post via FR 3.8.6) with localized CTA.</li><li><strong>Success:</strong> Immediate <code>TanStack Query</code> cache invalidation, live status badge update, and localized toast notification.</li><li><strong>Error / Retryable Failure:</strong> Structured inline banner displaying localized error reason mapped from <code>MSG01, MSG02, MSG03, MSG07, MSG42</code> without losing draft edits.</li></ul></li></ul><h2 id="_5-api-messaging-contract" tabindex="-1">5. API &amp; Messaging Contract <a class="header-anchor" href="#_5-api-messaging-contract" aria-label="Permalink to &quot;5. API &amp; Messaging Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Endpoint / Upstream Route</th><th style="text-align:left;">Auth / Security</th><th style="text-align:left;">Controller / Service Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST /api/v1/social/{platform}/connect-url?workspaceId={id}&amp;clientId={cid}</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Client</code>)</td><td style="text-align:left;"><code>SocialOAuthController.createConnectUrl()</code> (<code>publisher-service</code>) -&gt; verifies workspace caller via <code>GET /api/v1/internal/social-accounts/authorize-connect</code>, sets <code>bh_oauth_state</code> cookie, issues 60s single-use connect ticket</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/social/{platform}/authorize?ticket={ticket}</code></td><td style="text-align:left;">Single-use 60s Browser Ticket</td><td style="text-align:left;"><code>SocialOAuthController</code> -&gt; consumes ticket and redirects 302 to Meta / TikTok (PKCE S256) / Threads OAuth consent screen</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/social/{platform}/callback?code={code}&amp;state={state}</code></td><td style="text-align:left;">OAuth Provider Redirect + <code>bh_oauth_state</code></td><td style="text-align:left;"><code>MetaOAuthServiceImpl</code> / <code>TikTokOAuthServiceImpl</code> / <code>ThreadsOAuthServiceImpl</code> -&gt; exchanges code, encrypts token via AES-256-GCM, syncs via <code>POST /api/v1/internal/social-accounts/sync</code> (<code>X-Internal-Service-Key</code>)</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/social-accounts?workspaceId={workspaceId}</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>SocialAccountController</code> (<code>business-service</code>) -&gt; lists connected Workspace accounts without exposing encrypted token material</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>UNSUPPORTED_PLATFORM</code> (<code>400</code>, <code>MSG02</code>): Any platform outside <code>facebook</code>, <code>instagram</code>, <code>tiktok</code>, <code>threads</code> (e.g., Zalo OA or LinkedIn) is rejected.</li><li><code>OAUTH_STATE_MISMATCH</code> (<code>400</code>, <code>MSG42</code>): Missing/expired <code>bh_oauth_state</code> cookie or replayed connect ticket.</li><li><code>PROVIDER_ACCESS_DENIED</code> (<code>302 -&gt; ?status=cancelled</code>): User cancels consent on Meta/TikTok/Threads; redirects cleanly to <code>/workspaces/:id/connections</code> with localized warning toast.</li><li><strong>Duplicate Delivery / Network Retry:</strong> <code>PublishJobConsumer</code> enforces Redis lock <code>processingPostIds:{postId}:{platform}</code> (<code>30m</code> TTL) and <code>DefaultClassMapper</code> cross-service <code>PublishJobMessage</code> compatibility so broker redeliveries never double-post to a Client&#39;s live social feed.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Domain Index &amp; Sibling FRs:</strong> <a href="./../README.html">3.8 Publishing &amp; Social Index</a> · <a href="./../3-8-1-connect-social-account/spec.html">FR 3.8.1 — Connect Social Account</a> · <a href="./../3-8-7-track-post-status/spec.html">FR 3.8.7 — Track Post Status</a></li><li><strong>Consolidated Extension Module:</strong> <a href="./../../../modules/07-billing-publisher-and-observability/social-publisher-resilience/spec.html"><code>social-publisher-resilience</code></a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/07-publishing-social.html">BA 3.8 Publishing &amp; Social</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified across <code>brandhub-business-service</code> and <code>brandhub-publisher-service</code> JUnit suites, RabbitMQ + Redis lock integration checks, Web &amp; Mobile UI integration, <code>vi.json</code>/<code>en.json</code> parity, and Light/Dark mode verification (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> De-scoped platforms (Zalo OA), livestream broadcasting, or automated paid ad-spend boosting.</li></ul>',21)])])}const h=t(n,[["render",s]]);export{p as __pageData,h as default};
